const verticais = [
  { termo: 'pilates Goiânia', nicho: 'pilates', quantidade: 5 },
  { termo: 'CT de luta Goiânia', nicho: 'luta', quantidade: 5 },
  { termo: 'escola de natação Goiânia', nicho: 'natacao', quantidade: 5 },
  { termo: 'escola de idioma Goiânia', nicho: 'idioma', quantidade: 5 },
  { termo: 'personal trainer Goiânia', nicho: 'personal', quantidade: 5 },
  { termo: 'escola de ballet Goiânia', nicho: 'ballet', quantidade: 5 }
];
return verticais;

const results = $input.all()[0].json.results || [];
const verticai = $node["Mapear verticais"].json;
const quantidade = verticai.quantidade;

const contatos = results.slice(0, quantidade).map((place) => ({
  nome: place.name,
  telefone: place.formatted_address || '',
  google_maps_url: `https://maps.google.com/?q=${place.name}`,
  instagram_handle: '',
  vertical: verticai.nicho,
  mensagem_template: gerarMensagem(verticai.nicho, place.name)
}));

function gerarMensagem(nicho, nome) {
  const templates = {
    pilates: `Oi! Vi que você gerencia o ${nome}. Você usa algo pra gerenciar mensalidades e enviar cobranças pelo WhatsApp? Desenvolvemos uma solução feita pra estúdios de pilates. Bora ver uma demo?`,
    luta: `E aí! Vi que você coordena o ${nome}. Você usa sistema pra gerenciar alunos, cobrar mensalidade e enviar lembretes? Desenvolvemos uma solução exatamente pra CTs de luta. Bora ver?`,
    natacao: `Olá! Vi que você é responsável pela ${nome}. Você tem algum sistema pra gerenciar alunos e cobranças? Temos uma solução feita pra escolas de natação. Quer conhecer?`,
    idioma: `Oi! Vi que você gerencia o ${nome}. Você usa algo pra gerenciar mensalidades dos alunos e enviar cobranças pelo WhatsApp? Temos uma solução perfeita pra escolas de idioma. Bora ver?`,
    personal: `Fala! Vi que você é personal trainer no ${nome}. Você usa sistema pra gerenciar clientes e cobranças? Desenvolvemos uma solução pra personais que automatiza mensalidades. Quer conhecer?`,
    ballet: `Olá! Vi que você gerencia o ${nome}. Você tem algum sistema pra gerenciar alunas e cobranças? Temos uma solução feita pra escolas de ballet. Quer conferir?`
  };
  return templates[nicho] || 'Oi! Você gerencia um estabelecimento? Temos uma solução pra cobrança de mensalidades no WhatsApp. Posso fazer uma demo?';
}

return contatos;
